artifact.schema:
import type { LazyExoticComponent, ComponentType } from 'react';
import type { ZodSchema, infer as zinfer } from 'zod';

// ─── BRANDED ID — refactor-safe ─────────────────────────────────────
declare const __pattern_id__: unique symbol;
export type PatternId<S extends string = string> = S & { readonly [__pattern_id__]: true };
export const asPatternId = <S extends string>(s: S): PatternId<S> => s as PatternId<S>;

// ─── SLOT KINDS — LSP contract ──────────────────────────────────────
export type SlotKind =
  | 'data-display'    // tables, lists, grids, kpis
  | 'action'          // buttons, menus, toolbars
  | 'feedback'        // alerts, toasts, banners
  | 'navigation'      // breadcrumbs, tabs, sidebar items
  | 'layout'          // headers, footers, frames
  | 'form';           // inputs, wizards

// ─── CAPABILITY REQUIREMENTS — ISP ──────────────────────────────────
export type Capability = `${string}:${'read' | 'write' | 'stream'}` | string;

// ─── EXTENSIONS — OCP ───────────────────────────────────────────────
export interface PatternExtension<TConfig = unknown> {
  readonly id: string;
  readonly apply: (def: PatternDefinition<TConfig>) => PatternDefinition<TConfig>;
}

// ─── SELECTOR — pure mapping ctx → component props ──────────────────
export type Selector<TConfig, TProps> = (
  ctx: ResolvedContext,
  config: TConfig,
) => TProps;

// ─── VISIBILITY — pure predicate ────────────────────────────────────
export type VisibilityPredicate = (ctx: ResolvedContext) => boolean;

// ─── PATTERN DEFINITION — what definePattern returns ────────────────
export interface PatternDefinition<
  TConfig extends object = {},
  TProps extends object = {},
> {
  readonly id:         PatternId;
  readonly version:    `${number}.${number}.${number}`;
  readonly slotKind:   SlotKind;
  readonly requires:   ReadonlyArray<Capability>;
  readonly extensions: ReadonlyArray<PatternExtension>;

  readonly Component:  LazyExoticComponent<ComponentType<TProps>>;
  readonly selector:   Selector<TConfig, TProps>;
  readonly visibility: VisibilityPredicate;
  readonly config:     ZodSchema<TConfig>;

  // Factory: produces a PatternInstance bound to a slot of a View.
  readonly instance:   (opts?: PatternInstanceOptions<TConfig>) => PatternInstance<TConfig>;
}

// ─── PATTERN INSTANCE — bound, configured pattern for a slot ────────
export interface PatternInstanceOptions<TConfig> {
  readonly config?:  Partial<TConfig>;
  readonly slots?:   Record<string, ComponentType<any> | LazyExoticComponent<any>>;
  readonly on?:      Partial<Record<string, (payload: unknown) => void>>;  // event hooks (L2)
  readonly key?:     string;
}

export interface PatternInstance<TConfig> {
  readonly definitionId: PatternId;
  readonly options:      PatternInstanceOptions<TConfig>;
  readonly _brand:       'PatternInstance';
}

// ─── definePattern — the factory ────────────────────────────────────
export function definePattern<TConfig extends object, TProps extends object>(
  spec: {
    id:         PatternId;
    version:    `${number}.${number}.${number}`;
    slotKind:   SlotKind;
    requires:   ReadonlyArray<Capability>;
    extensions?: ReadonlyArray<PatternExtension>;
    Component:  LazyExoticComponent<ComponentType<TProps>>;
    selector:   Selector<TConfig, TProps>;
    visibility?: VisibilityPredicate;
    config:     ZodSchema<TConfig>;
  }
): PatternDefinition<TConfig, TProps>;

