// packages/patterns/product-table/src/index.ts
import { definePattern, asPatternId, withTelemetry, withErrorBoundary, withFeatureFlag } from '@surte/core';
import { lazy } from 'react';
import { z } from 'zod';
import { reselectStable } from '@surte/core/selectors';

export const PRODUCT_TABLE_PATTERN_ID = asPatternId('pattern.product-table');

const ConfigSchema = z.object({
  density: z.enum(['compact', 'comfortable']).default('comfortable'),
  pageSize: z.number().int().positive().default(20),
  showSku: z.boolean().default(true),
});

export const ProductTablePattern = definePattern({
  id:       PRODUCT_TABLE_PATTERN_ID,
  version:  '1.0.0',
  slotKind: 'data-display',
  requires: ['products:read', 'session:read'] as const,
  extensions: [
    withTelemetry({ events: ['rowSelected', 'sortChanged'] }),
    withErrorBoundary({ fallbackId: 'product-table-error' }),
    withFeatureFlag('products.table.v2'),
  ],
  Component: lazy(() => import('./ProductTable.component').then(m => ({ default: m.ProductTable }))),
  selector:  reselectStable((ctx, config) => ({
    products: ctx['products:read'].list({ limit: config.pageSize }),
    density:  config.density,
    showSku:  config.showSku,
  })),
  visibility: (ctx) => ctx['session:read'].permissions.has('products.read'),
  config:     ConfigSchema,
});
